Pulled the relevant guidance (RN stack rules, touch-target/safe-area/dark-mode checklist, and destructive-action conventions: `confirmation-dialogs`, `destructive-emphasis`, `destructive-nav-separation`, `undo-support`). Here's a complete, self-contained screen that follows them — grouped settings rows, dark-mode-aware tokens, 44/48pt touch targets, safe-area insets, and a two-step native confirmation before the irreversible delete call.

**Assumed deps** (standard in most RN/Expo apps — swap if you're on a different icon/safe-area setup): `@expo/vector-icons`, `react-native-safe-area-context`.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useMemo, useState } from 'react';
import {
  View,
  Text,
  Pressable,
  ScrollView,
  Image,
  Switch,
  Alert,
  StyleSheet,
  Platform,
  ActivityIndicator,
  useColorScheme,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';

type IconName = keyof typeof Ionicons.glyphMap;

interface Profile {
  name: string;
  email: string;
  avatarUrl?: string;
}

type SettingsRowKind = 'nav' | 'switch' | 'value' | 'destructive';

interface SettingsItemBase {
  key: string;
  label: string;
  icon: IconName;
}

interface NavItem extends SettingsItemBase {
  kind: 'nav' | 'destructive';
  onPress: () => void;
}

interface ValueItem extends SettingsItemBase {
  kind: 'value';
  value: string;
  onPress?: () => void;
}

interface SwitchItem extends SettingsItemBase {
  kind: 'switch';
  switchValue: boolean;
  onToggle: (next: boolean) => void;
}

type SettingsItem = NavItem | ValueItem | SwitchItem;

interface SettingsSection {
  key: string;
  title?: string;
  items: SettingsItem[];
}

interface AccountSettingsScreenProps {
  profile: Profile;
  sections: SettingsSection[];
  onEditProfile: () => void;
  /** Perform the actual deletion. Throw to signal failure. */
  onDeleteAccount: () => Promise<void>;
  /** Called after onDeleteAccount resolves — e.g. clear auth state / navigate to logged-out stack. */
  onAccountDeleted: () => void;
  onBack?: () => void;
}

function useTheme() {
  const scheme = useColorScheme();
  const isDark = scheme === 'dark';
  return useMemo(
    () => ({
      isDark,
      background: isDark ? '#000000' : '#F2F2F7',
      surface: isDark ? '#1C1C1E' : '#FFFFFF',
      border: isDark ? '#38383A' : '#E5E5EA',
      textPrimary: isDark ? '#FFFFFF' : '#1C1C1E',
      textSecondary: isDark ? '#9A9A9E' : '#6E6E73',
      accent: '#0A84FF',
      danger: '#FF3B30',
      dangerBg: isDark ? 'rgba(255,59,48,0.16)' : 'rgba(255,59,48,0.10)',
      iconBg: isDark ? '#2C2C2E' : '#E9E9EC',
    }),
    [isDark],
  );
}

type Theme = ReturnType<typeof useTheme>;

function initials(name: string) {
  return name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');
}

function ProfileRow({
  profile,
  onPress,
  theme,
}: {
  profile: Profile;
  onPress: () => void;
  theme: Theme;
}) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${profile.name}, ${profile.email}`}
      accessibilityHint="Opens profile editing"
      android_ripple={{ color: theme.border }}
      style={({ pressed }) => [
        styles.profileRow,
        { backgroundColor: theme.surface, borderColor: theme.border },
        Platform.OS === 'ios' && pressed && { opacity: 0.6 },
      ]}
    >
      {profile.avatarUrl ? (
        <Image
          source={{ uri: profile.avatarUrl }}
          style={styles.avatar}
          width={56}
          height={56}
          accessible={false}
        />
      ) : (
        <View
          style={[styles.avatar, styles.avatarFallback, { backgroundColor: theme.accent }]}
          accessible={false}
        >
          <Text style={styles.avatarInitials}>{initials(profile.name)}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: theme.textPrimary }]} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text style={[styles.profileEmail, { color: theme.textSecondary }]} numberOfLines={1}>
          {profile.email}
        </Text>
      </View>
      <Ionicons name="chevron-forward" size={20} color={theme.textSecondary} />
    </Pressable>
  );
}

function RowIcon({ name, tint, bg }: { name: IconName; tint: string; bg: string }) {
  return (
    <View style={[styles.rowIconWrap, { backgroundColor: bg }]}>
      <Ionicons name={name} size={18} color={tint} />
    </View>
  );
}

function SettingsRow({
  item,
  theme,
  disabled,
  isLast,
}: {
  item: SettingsItem;
  theme: Theme;
  disabled?: boolean;
  isLast: boolean;
}) {
  const isDanger = item.kind === 'destructive';
  const tint = isDanger ? theme.danger : theme.accent;
  const iconBg = isDanger ? theme.dangerBg : theme.iconBg;

  if (item.kind === 'switch') {
    return (
      <Pressable
        onPress={() => item.onToggle(!item.switchValue)}
        disabled={disabled}
        accessibilityRole="switch"
        accessibilityState={{ checked: item.switchValue, disabled: !!disabled }}
        accessibilityLabel={item.label}
        hitSlop={8}
        android_ripple={{ color: theme.border }}
        style={({ pressed }) => [
          styles.row,
          !isLast && { borderBottomWidth: 1, borderBottomColor: theme.border },
          Platform.OS === 'ios' && pressed && { opacity: 0.6 },
        ]}
      >
        <RowIcon name={item.icon} tint={tint} bg={iconBg} />
        <Text style={[styles.rowLabel, { color: theme.textPrimary }]}>{item.label}</Text>
        <Switch
          value={item.switchValue}
          onValueChange={item.onToggle}
          disabled={disabled}
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
        />
      </Pressable>
    );
  }

  const onPress = item.kind === 'value' ? item.onPress : item.onPress;
  const isInteractive = typeof onPress === 'function';

  return (
    <Pressable
      onPress={onPress}
      disabled={disabled || !isInteractive}
      accessibilityRole={isInteractive ? 'button' : undefined}
      accessibilityLabel={item.kind === 'value' ? `${item.label}, ${item.value}` : item.label}
      accessibilityHint={isDanger ? 'Irreversible action, confirmation required' : undefined}
      hitSlop={8}
      android_ripple={isInteractive ? { color: theme.border } : undefined}
      style={({ pressed }) => [
        styles.row,
        !isLast && { borderBottomWidth: 1, borderBottomColor: theme.border },
        Platform.OS === 'ios' && pressed && isInteractive && { opacity: 0.6 },
        disabled && { opacity: 0.5 },
      ]}
    >
      <RowIcon name={item.icon} tint={tint} bg={iconBg} />
      <Text style={[styles.rowLabel, { color: isDanger ? theme.danger : theme.textPrimary }]}>
        {item.label}
      </Text>
      {item.kind === 'value' && (
        <Text style={[styles.rowValue, { color: theme.textSecondary }]} numberOfLines={1}>
          {item.value}
        </Text>
      )}
      {isInteractive && !isDanger && (
        <Ionicons name="chevron-forward" size={18} color={theme.textSecondary} />
      )}
    </Pressable>
  );
}

function Section({
  section,
  theme,
  disabled,
}: {
  section: SettingsSection;
  theme: Theme;
  disabled?: boolean;
}) {
  return (
    <View style={styles.section}>
      {section.title && (
        <Text style={[styles.sectionTitle, { color: theme.textSecondary }]}>
          {section.title.toUpperCase()}
        </Text>
      )}
      <View style={[styles.sectionCard, { backgroundColor: theme.surface, borderColor: theme.border }]}>
        {section.items.map((item, index) => (
          <SettingsRow
            key={item.key}
            item={item}
            theme={theme}
            disabled={disabled}
            isLast={index === section.items.length - 1}
          />
        ))}
      </View>
    </View>
  );
}

export default function AccountSettingsScreen({
  profile,
  sections,
  onEditProfile,
  onDeleteAccount,
  onAccountDeleted,
  onBack,
}: AccountSettingsScreenProps) {
  const theme = useTheme();
  const insets = useSafeAreaInsets();
  const [isDeleting, setIsDeleting] = useState(false);

  const runDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
      onAccountDeleted();
    } catch (err) {
      Alert.alert(
        'Couldn’t delete account',
        err instanceof Error ? err.message : 'Something went wrong. Please try again.',
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount, onAccountDeleted]);

  const confirmDelete = useCallback(() => {
    Alert.alert(
      'Delete account?',
      'This will permanently delete your profile, settings, and activity.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => {
            // Second confirmation — irreversible action, no undo available.
            Alert.alert(
              'Are you absolutely sure?',
              'Your account and all associated data will be erased and cannot be recovered after this.',
              [
                { text: 'Cancel', style: 'cancel' },
                { text: 'Delete Permanently', style: 'destructive', onPress: runDelete },
              ],
            );
          },
        },
      ],
    );
  }, [runDelete]);

  const allSections = useMemo<SettingsSection[]>(
    () => [
      ...sections,
      {
        key: 'danger-zone',
        items: [
          {
            key: 'delete-account',
            kind: 'destructive',
            label: isDeleting ? 'Deleting…' : 'Delete Account',
            icon: 'trash-outline',
            onPress: confirmDelete,
          },
        ],
      },
    ],
    [sections, confirmDelete, isDeleting],
  );

  return (
    <View style={[styles.screen, { backgroundColor: theme.background }]}>
      <View style={[styles.header, { paddingTop: insets.top + 8, borderBottomColor: theme.border }]}>
        {onBack && (
          <Pressable
            onPress={onBack}
            hitSlop={12}
            accessibilityRole="button"
            accessibilityLabel="Go back"
            style={styles.backButton}
          >
            <Ionicons name="chevron-back" size={26} color={theme.accent} />
          </Pressable>
        )}
        <Text style={[styles.headerTitle, { color: theme.textPrimary }]}>Account</Text>
      </View>

      <ScrollView
        contentContainerStyle={[styles.content, { paddingBottom: insets.bottom + 32 }]}
        contentInsetAdjustmentBehavior="automatic"
      >
        <ProfileRow profile={profile} onPress={onEditProfile} theme={theme} />

        {allSections.map((section) => (
          <Section key={section.key} section={section} theme={theme} disabled={isDeleting} />
        ))}
      </ScrollView>

      {isDeleting && (
        <View style={styles.overlay} accessibilityLiveRegion="polite">
          <ActivityIndicator size="large" color={theme.danger} />
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingBottom: 12,
    borderBottomWidth: 1,
  },
  backButton: {
    minWidth: 44,
    minHeight: 44,
    justifyContent: 'center',
    marginLeft: -8,
  },
  headerTitle: {
    fontSize: 20,
    fontWeight: '700',
  },
  content: {
    paddingHorizontal: 16,
    paddingTop: 16,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: 16,
    borderRadius: 14,
    borderWidth: 1,
    marginBottom: 24,
    minHeight: 48,
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
  },
  avatarFallback: {
    justifyContent: 'center',
    alignItems: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 20,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
    marginLeft: 14,
    marginRight: 8,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
    marginTop: 2,
  },
  section: {
    marginBottom: 24,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    marginBottom: 8,
    marginLeft: 4,
    letterSpacing: 0.4,
  },
  sectionCard: {
    borderRadius: 14,
    borderWidth: 1,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 14,
    minHeight: 52,
  },
  rowIconWrap: {
    width: 30,
    height: 30,
    borderRadius: 8,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 12,
  },
  rowLabel: {
    flex: 1,
    fontSize: 16,
  },
  rowValue: {
    fontSize: 15,
    marginRight: 6,
    maxWidth: 140,
  },
  overlay: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: 'rgba(0,0,0,0.25)',
    justifyContent: 'center',
    alignItems: 'center',
  },
});
```

**Example wiring** (mock data — replace with your navigation/API calls):

```tsx
// Usage, e.g. inside a stack screen
import AccountSettingsScreen from './AccountSettingsScreen';
import { useState } from 'react';

function AccountSettingsContainer({ navigation }: any) {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [darkMode, setDarkMode] = useState(false);

  return (
    <AccountSettingsScreen
      profile={{ name: 'Alex Rivera', email: 'alex.rivera@example.com' }}
      onBack={() => navigation.goBack()}
      onEditProfile={() => navigation.navigate('EditProfile')}
      sections={[
        {
          key: 'account',
          title: 'Account',
          items: [
            { key: 'edit-profile', kind: 'nav', label: 'Edit Profile', icon: 'person-outline', onPress: () => navigation.navigate('EditProfile') },
            { key: 'password', kind: 'nav', label: 'Change Password', icon: 'lock-closed-outline', onPress: () => navigation.navigate('ChangePassword') },
          ],
        },
        {
          key: 'preferences',
          title: 'Preferences',
          items: [
            { key: 'push', kind: 'switch', label: 'Push Notifications', icon: 'notifications-outline', switchValue: pushEnabled, onToggle: setPushEnabled },
            { key: 'dark-mode', kind: 'switch', label: 'Dark Mode', icon: 'moon-outline', switchValue: darkMode, onToggle: setDarkMode },
          ],
        },
        {
          key: 'about',
          title: 'About',
          items: [
            { key: 'version', kind: 'value', label: 'Version', icon: 'information-circle-outline', value: '4.12.0 (1832)' },
            { key: 'logout', kind: 'nav', label: 'Log Out', icon: 'log-out-outline', onPress: () => {/* sign out */} },
          ],
        },
      ]}
      onDeleteAccount={async () => {
        const res = await fetch('/api/account', { method: 'DELETE' });
        if (!res.ok) throw new Error('Request failed. Please try again.');
      }}
      onAccountDeleted={() => navigation.reset({ index: 0, routes: [{ name: 'SignedOut' }] })}
    />
  );
}
```

Notes on what the guidance drove:
- Delete is its own section at the bottom, red icon/text, separated from normal nav rows (`destructive-nav-separation`), and requires two native confirmations (`confirmation-dialogs`) before calling `onDeleteAccount`.
- All rows are ≥48–52pt tall; back button and switch rows use `hitSlop`/min 44×44 targets.
- Switch rows are single accessibility elements (`accessibilityRole="switch"`, state exposed, inner `Switch` hidden from the tree) rather than double-announcing.
- Colors come from a light/dark token object (`useColorScheme`) rather than hardcoded hex per row, and borders/dividers stay visible in both themes.
- `useSafeAreaInsets` pads the header and scroll content so nothing sits under the status bar or home indicator.
- A full-screen overlay + disabled rows during the delete request prevent double taps and give loading feedback, with the error path surfaced via `Alert` rather than silently failing.
